refentry.refsect1:
&reftitle.errors;

 Throws an Io\Poll\InactiveWatcherException
 if the watcher was already removed, or if its context was destroyed.

  &reftitle.examples;

   Io\Poll\Watcher::remove example


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Io\Poll\InactiveWatcherException;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$watcher = $context->add(new StreamPollHandle($reader), [Event::Read]);

fwrite($writer, 'ping');
var_dump(count($context->wait(Duration::fromMilliseconds(10))));

$watcher->remove();
var_dump(count($context->wait(Duration::fromMilliseconds(10))));

try {
    $watcher->remove();
} catch (InactiveWatcherException $exception) {
    echo $exception->getMessage(), PHP_EOL;
}


   &example.outputs;


int(1)
int(0)
Cannot remove inactive watcher
